  let third=root.with_extension("history-third-owner");let(_,third_result)=crate::local_database::joint_archive::tests::import_existing_canonical_archive(&next,third.clone(),false).await;assert!(third_result["candidate"]["assets"].as_array().unwrap().is_empty());let joints:Value=serde_json::from_str(third_result["imported_provenance"]["joint_imports_json"].as_str().unwrap()).unwrap();let previous:Value=serde_json::from_str(joints[0]["receipt_json"].as_str().unwrap()).unwrap();assert_eq!(previous["imported_provenance"]["local_dispositions_json"],raw);assert!(!third.join(".starlane/local-cover-producers").exists());
