 #[tokio::test]async fn self_consistent_portable_disposition_contract_corruption_refuses_before_destination_creation(){
  let _serial=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());let(root,owner,request)=original("portable-disposition-negative",true).await;let source=root.with_extension("portable-disposition.zip");let report=publish(owner,source.clone()).await;
  let mut zip=zip::ZipArchive::new(File::open(&source).unwrap()).unwrap();let mut original=std::collections::BTreeMap::new();for i in 0..zip.len(){let mut entry=zip.by_index(i).unwrap();let mut bytes=Vec::new();std::io::Read::read_to_end(&mut entry,&mut bytes).unwrap();original.insert(entry.name().to_string(),bytes);}drop(zip);
  for mode in ["nonzero-links","foreign-completion-stamp","wrong-completion-state","duplicate-operation","live-reference","missing-dispositions","extra-payload"]{
   let mut entries=original.clone();let mut rows:Value=serde_json::from_slice(&entries["starlane-native/local-dispositions.json"]).unwrap();let mut evidence:Value=serde_json::from_str(rows[0]["evidence_json"].as_str().unwrap()).unwrap();let mut receipt:Value=serde_json::from_str(evidence["receipt_json"].as_str().unwrap()).unwrap();let mut completion:Value=serde_json::from_str(receipt["native_completion_json"].as_str().unwrap()).unwrap();
   match mode{"nonzero-links"=>completion["payload_after"]["links"]=json!(1),"foreign-completion-stamp"=>receipt["native_completion_stamp"]["inode"]=json!(receipt["native_completion_stamp"]["inode"].as_u64().unwrap()+1),"wrong-completion-state"=>completion["state"]=json!("canonical_committed"),_=>{}}
   let raw=serde_json::to_string(&completion).unwrap();receipt["native_completion_json"]=json!(raw);receipt["native_completion_stamp"]["length"]=json!(receipt["native_completion_json"].as_str().unwrap().len());evidence["receipt_json"]=json!(serde_json::to_string(&receipt).unwrap());let raw=serde_json::to_string(&evidence).unwrap();rows[0]["evidence_sha256"]=json!(sha(raw.as_bytes()));rows[0]["evidence_json"]=json!(raw);
   if mode=="duplicate-operation"{let row=rows[0].clone();rows.as_array_mut().unwrap().push(row)}
   let mut snapshot:Value=serde_json::from_slice(&entries["vault.json"]).unwrap();if mode=="live-reference"{snapshot["drafts"][0]["cover_image"]=json!(format!("starlane-local-attachment://{}",request.operation_id));}entries.insert("vault.json".into(),serde_json::to_vec(&snapshot).unwrap());entries.insert("starlane-native/local-dispositions.json".into(),serde_json::to_vec(&rows).unwrap());let mut manifest:Value=serde_json::from_slice(&entries["starlane-native/manifest.json"]).unwrap();manifest["snapshot_sha256"]=json!(sha(&entries["vault.json"]));manifest["local_dispositions_sha256"]=json!(sha(&entries["starlane-native/local-dispositions.json"]));entries.insert("starlane-native/manifest.json".into(),serde_json::to_vec(&manifest).unwrap());
   if mode=="missing-dispositions"{entries.remove("starlane-native/local-dispositions.json");}if mode=="extra-payload"{entries.insert("starlane-native/discarded-payload.bin".into(),vec![1,2,3]);}
   let damaged=root.with_extension(format!("{mode}.zip"));let mut writer=zip::ZipWriter::new(File::create(&damaged).unwrap());for(name,bytes)in entries{writer.start_file(name,zip::write::SimpleFileOptions::default()).unwrap();writer.write_all(&bytes).unwrap();}writer.finish().unwrap();let destination=root.with_extension(format!("{mode}-destination"));let error=vault::archive_admission::prepare("none",&damaged,&destination.join("assets")).err().unwrap();assert!(!error.is_empty());assert!(!destination.exists());fs::remove_file(damaged).unwrap();
  }
  cleanup_publication(&source,&report);fs::remove_dir_all(root).unwrap();
 }

